// === Tab: mySketch ===
// 宣告一個用於儲存所有星星物件的陣列
let stars;

// 宣告變數來儲存畫布的尺寸
let canvasWidth;
let canvasHeight;

function setup() {
    // 根據視窗高度計算畫布尺寸 (保持長寬比)
    canvasHeight = window.innerHeight * 0.8;
    canvasWidth = (1080 / 1920) * canvasHeight;
    createCanvas(canvasWidth, canvasHeight);
    stars = [];
    // 循環創建 200 顆星星
    for (let i = 0; i < 200; i++) {
        stars.push(new Star());
    }
}

function draw() {
    // 設定深藍色背景 (模擬夜晚的天空)
    background(10, 10, 30); 

    // 遍歷所有星星
    for (let i = 0; i < stars.length; i++) {
        // 更新星星的位置
        stars[i].update();
        // 繪製星星
        stars[i].display();

        // 內層循環，將當前星星與後面的所有星星連接 (避免重複連線)
        for (let j = i + 1; j < stars.length; j++) {
            stars[i].connect(stars[j]);
        }
    }
}

// 定義 Star (星星) 類別
class Star {
    constructor() {
        // 隨機設置星星的初始 x 座標
        this.x = random(width);
        // 隨機設置星星的初始 y 座標
        this.y = random(height);
        // 隨機設置星星的大小 (1 到 8 像素)
        this.size = random(1, 8);
        // 隨機設置星星的亮度/透明度 (alpha 值)，模擬不同的光照強度
        this.alpha = random(1, 255); 
        // 隨機設置小的水平移動速度 (x 軸)
        this.xSpeed = random(-0.5, 0.5);
        // 隨機設置小的垂直移動速度 (y 軸)
        this.ySpeed = random(-0.5, 0.5);
    }

    update() {
        // ========== [新功能: 滑鼠引力拉動] ==========

      // 檢查滑鼠是否在畫布範圍內 ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) 和 (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) 是 p5.js 內建的變數)
    if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {

        // 計算星星與滑鼠之間的距離
        let d_mouse = dist(this.x, this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

        // 設定引力影響範圍 (例如：150 像素)
        let safe_distance = 300; 

        if (d_mouse < safe_distance) {
            // 根據距離映射引力強度：越近，拉力越強 (0.2 到 0)
            let strength = map(d_mouse, 0, safe_distance, 0.2, 0); 

            // 計算指向滑鼠的方向向量 (dx, dy)
            let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.x;
            let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.y;

            // 應用溫和的拉力到速度上 (0.001 是調整整體靈敏度的係數)
            this.xSpeed += dx * strength * 0.001;
            this.ySpeed += dy * strength * 0.001;
        }
      }


        // ==========================================

        // 根據速度更新位置
        this.x += this.xSpeed;
        this.y += this.ySpeed;

        // 處理邊界，實現環繞效果 (從一邊移出，從對邊出現)
        if (this.x < 0) this.x = width;
        if (this.x > width) this.x = 0;
        if (this.y < 0) this.y = height;
        if (this.y > height) this.y = 0;

        // 輕微改變速度，製造柔和的移動和「網路」般的呼吸感
        this.xSpeed += random(-0.01, 0.01);
        this.ySpeed += random(-0.01, 0.01);
        // 限制速度在一個較小的範圍內，保持緩慢移動
        this.xSpeed = constrain(this.xSpeed, -1, 1);
        this.ySpeed = constrain(this.ySpeed, -1, 1);
    }

    display() {
        // 移除邊框
        noStroke();
        // 設定顏色為白色，亮度由 this.alpha 決定
        fill(255, 255, 255, this.alpha);
        // 繪製星星 (圓形)
        ellipse(this.x, this.y, this.size, this.size);
    }

    connect(other) {
        // 計算當前星星與另一顆星星之間的距離
        let d = dist(this.x, this.y, other.x, other.y);

        // 如果距離小於 100 像素，則進行連線
        if (d < 100) { 
            // 根據距離映射連線的透明度：距離越近，線越亮 (alpha 越大)
            let alpha = map(d, 0, 100, 150, 0); 
            // 設定連線的顏色為白色，亮度由計算出的 alpha 決定
            stroke(255, 255, 255, alpha);
            // 繪製連線
            line(this.x, this.y, other.x, other.y);
        }
    }
}

// 當視窗大小改變時，重新調整畫布大小
function windowResized() {
    // 重新計算畫布尺寸 (保持長寬比)
    canvasHeight = window.innerHeight * 0.8;
    canvasWidth = (1080 / 1920) * canvasHeight;
    resizeCanvas(canvasWidth, canvasHeight);
}

